  1→/**
  2→ * @fileoverview HTTP status/control API and docs/static file server.
  3→ *
  4→ * Responsibilities:
  5→ * - expose bridge status/health for the manager UI
  6→ * - provide admin-protected control endpoints (logout, config reload, sessions)
  7→ * - serve documentation assets under `/docs`
  8→ *
  9→ * @module api/status
 10→ * @see {@link startStatusServer} Start the HTTP server and route requests
 11→ * @see {@link updateStatus} Update in-memory bridge status
 12→ * @see {@link getStatus} Read current status snapshot
 13→ * 
 14→ * ## Endpoints
 15→ * 
 16→ * | Method | Path | Description |
 17→ * |--------|------|-------------|
 18→ * | GET | /api/status | Current bridge status (JSON) |
 19→ * | GET | /api/health | Lightweight health check (Go TUI) |
 20→ * | POST | /api/logout | Disconnect WhatsApp (admin token required) |
 21→ * | POST | /api/whatsapp/start | Start WhatsApp bridge session (admin token required) |
 22→ * | POST | /api/whatsapp/restart | Restart WhatsApp bridge session (admin token required) |
 23→ * | POST | /api/config/reload | Reload mounted `.env` into process env (admin token required) |
 24→ * | GET | /api/sessions | List sessions (admin token required) |
 25→ * | GET | /api/sessions/:id | Read one session (admin token required) |
 26→ * | DELETE | /api/sessions/:id | Delete one session (admin token required) |
 27→ * | POST | /api/sessions/:id/clear | Clear one session history (admin token required) |
 28→ * | GET | /docs/* | Documentation site (static) |
 29→ */
 30→
 31→import http from 'http';
 32→import fs from 'fs';
 33→import path from 'path';
 34→import { logger } from '../utils/logger.js';
 35→import { env } from '../config/env.js';
 36→import { getVersion } from '../utils/version.js';
 37→import { getSessionManager } from '../session/manager.js';
 38→import { validateRuntimeEnvUpdates } from '../config/env.js';
 39→import { getNotificationMetrics, type NotificationMetrics } from '../agent/notifications.js';
 40→import { getWhatsAppFormatMetrics, type WhatsAppFormatMetrics } from '../agent/whatsapp-format.js';
 41→
 42→// =============================================================================
 43→// CONFIGURATION
 44→// =============================================================================
 45→
 46→/** HTTP server port (internal to Docker network) */
 47→const PORT = 8765;
 48→
 49→/** Path to documentation files */
 50→const DOCS_PATH = '/app/docs';
 51→const ENV_PATH = '/app/.env';
 52→const SESSION_ID_REGEX = /^[a-zA-Z0-9_-]+$/;
 53→
 54→// =============================================================================
 55→// TYPES
 56→// =============================================================================
 57→
 58→/**
 59→ * Status payload returned by `GET /api/status`.
 60→ */
 61→export interface BridgeStatus {
 62→  /** Current connection state */
 63→  state: 'initializing' | 'qr_pending' | 'authenticated' | 'disconnected' | 'error';
 64→  /** QR code data (when state is qr_pending) */
 65→  qrCode: string | null;
 66→  /** URL to view QR code in browser */
 67→  qrUrl: string | null;
 68→  /** Uptime in seconds */
 69→  uptime: number;
 70→  /** Total messages processed */
 71→  messageCount: number;
 72→  /** Last error message (if any) */
 73→  lastError: string | null;
 74→  /** Current version */
 75→  version: string;
 76→  /** Notification formatter path/fallback counters */
 77→  notificationMetrics: NotificationMetrics;
 78→  /** WhatsApp response formatting and chunking counters */
 79→  responseFormattingMetrics: WhatsAppFormatMetrics;
 80→}
 81→
 82→// =============================================================================
 83→// GLOBAL STATE
 84→// =============================================================================
 85→
 86→/** Global status (updated by bridge events) */
 87→let status: BridgeStatus = {
 88→  state: 'initializing',
 89→  qrCode: null,
 90→  qrUrl: null,
 91→  uptime: 0,
 92→  messageCount: 0,
 93→  lastError: null,
 94→  version: getVersion(),
 95→  notificationMetrics: getNotificationMetrics(),
 96→  responseFormattingMetrics: getWhatsAppFormatMetrics(),
 97→};
 98→
 99→/** Server start time for uptime calculation */
100→const startTime = Date.now();
101→
102→/** Callback for logout action */
103→let logoutCallback: (() => Promise<void>) | null = null;
104→let startCallback: (() => Promise<void>) | null = null;
105→let restartCallback: (() => Promise<void>) | null = null;
106→let envWatcherInitialized = false;
107→
108→/** Optional admin token for protected endpoints (logout/config/session APIs). */
109→const ADMIN_TOKEN = env.ADMIN_TOKEN || '';
110→
111→/** Returns true when request is authorized for admin-only endpoints. */
112→function isAdminAuthorized(req: http.IncomingMessage): boolean {
113→  // If ADMIN_TOKEN is unset, allow local TUI/admin workflows without token wiring.
114→  if (!ADMIN_TOKEN) return true;
115→  return req.headers.authorization === `Bearer ${ADMIN_TOKEN}`;
116→}
117→
118→/**
119→ * Register callback used by `POST /api/logout`.
120→ */
121→export function setLogoutCallback(callback: () => Promise<void>): void {
122→  logoutCallback = callback;
123→}
124→
125→/** Register callback used by WhatsApp start/restart control endpoints. */
126→export function setWhatsAppControlCallbacks(callbacks: {
127→  start?: () => Promise<void>;
128→  restart?: () => Promise<void>;
129→}): void {
130→  startCallback = callbacks.start ?? null;
131→  restartCallback = callbacks.restart ?? null;
132→}
133→
134→/**
135→ * Execute the registered logout callback, if available.
136→ *
137→ * @returns `true` when callback runs successfully; otherwise `false`
138→ */
139→export async function triggerLogout(): Promise<boolean> {
140→  if (logoutCallback) {
141→    try {
142→      await logoutCallback();
143→      return true;
144→    } catch (error) {
145→      logger.error('Logout failed:', error);
146→      return false;
147→    }
148→  }
149→  return false;
150→}
151→
152→/** Execute the registered WhatsApp start callback, if available. */
153→export async function triggerWhatsAppStart(): Promise<boolean> {
154→  if (!startCallback) return false;
155→  try {
156→    await startCallback();
157→    return true;
158→  } catch (error) {
159→    logger.error('WhatsApp start failed:', error);
160→    return false;
161→  }
162→}
163→
164→/** Execute the registered WhatsApp restart callback, if available. */
165→export async function triggerWhatsAppRestart(): Promise<boolean> {
166→  if (!restartCallback) return false;
167→  try {
168→    await restartCallback();
169→    return true;
170→  } catch (error) {
171→    logger.error('WhatsApp restart failed:', error);
172→    return false;
173→  }
174→}
175→
176→// =============================================================================
177→// STATUS FUNCTIONS
178→// =============================================================================
179→
180→/**
181→ * Merge partial fields into the in-memory status object.
182→ *
183→ * @param update - Status fields to overwrite
184→ */
185→export function updateStatus(update: Partial<BridgeStatus>): void {
186→  status = { ...status, ...update };
187→  logger.debug('Status updated:', { state: status.state });
188→}
189→
190→/**
191→ * Increment processed-message counter for status reporting.
192→ */
193→export function incrementMessageCount(): void {
194→  status.messageCount++;
195→}
196→
197→/**
198→ * Return a status snapshot with computed uptime.
199→ *
200→ * @returns Current status payload
201→ */
202→export function getStatus(): BridgeStatus {
203→  return {
204→    ...status,
205→    uptime: Math.floor((Date.now() - startTime) / 1000),
206→    notificationMetrics: getNotificationMetrics(),
207→    responseFormattingMetrics: getWhatsAppFormatMetrics(),
208→  };
209→}
210→
211→/** Returns true when session-id uses supported URL-safe grammar. */
212→export function isValidSessionId(sessionId: string): boolean {
213→  return SESSION_ID_REGEX.test(sessionId);
214→}
215→
216→/**
217→ * Reload process.env from mounted .env file.
218→ *
219→ * @returns Updated key names
220→ */
221→function reloadEnvFromFile(): string[] {
222→  if (!fs.existsSync(ENV_PATH)) {
223→    throw new Error('.env not mounted');
224→  }
225→
226→  const envContent = fs.readFileSync(ENV_PATH, 'utf-8');
227→  const updatedKeys: string[] = [];
228→  const pendingUpdates: Record<string, string> = {};
229→
230→  for (const line of envContent.split('\n')) {
231→    const trimmed = line.trim();
232→    if (!trimmed || trimmed.startsWith('#')) continue;
233→
234→    const eqIndex = trimmed.indexOf('=');
235→    if (eqIndex === -1) continue;
236→
237→    const key = trimmed.substring(0, eqIndex).trim();
238→    let value = trimmed.substring(eqIndex + 1).trim();
239→    if (!key) continue;
240→
241→    if ((value.startsWith('"') && value.endsWith('"')) ||
242→      (value.startsWith("'") && value.endsWith("'"))) {
243→      value = value.slice(1, -1);
244→    }
245→    pendingUpdates[key] = value;
246→  }
247→
248→  const validation = validateRuntimeEnvUpdates(pendingUpdates);
249→  if (!validation.valid) {
250→    const first = validation.invalid[0];
251→    throw new Error(`Invalid runtime config updates: ${first?.key ?? 'unknown'} ${first?.reason ?? ''}`.trim());
252→  }
253→
254→  for (const [key, value] of Object.entries(pendingUpdates)) {
255→    if (process.env[key] !== value) {
256→      process.env[key] = value;
257→      updatedKeys.push(key);
258→    }
259→  }
260→
261→  return updatedKeys;
262→}
263→
264→/**
265→ * Start the HTTP server and register all API/docs routes.
266→ */
267→export function startStatusServer(): void {
268→  const server = http.createServer(async (req, res) => {
269→    const url = req.url || '/';
270→
271→    // CORS headers for local development
272→    res.setHeader('Access-Control-Allow-Origin', '*');
273→
274→    // API Routes
275→    if (req.method === 'GET' && url === '/api/status') {
276→      res.setHeader('Content-Type', 'application/json');
277→      res.writeHead(200);
278→      res.end(JSON.stringify(getStatus()));
279→      return;
280→    }
281→
282→    if (req.method === 'GET' && url === '/api/health') {
283→      res.setHeader('Content-Type', 'application/json');
284→      res.writeHead(200);
285→      res.end(JSON.stringify({ healthy: true }));
286→      return;
287→    }
288→
289→    // Logout/Disconnect endpoint (requires admin token)
290→    if (req.method === 'POST' && url === '/api/logout') {
291→      res.setHeader('Content-Type', 'application/json');
292→
293→      if (!isAdminAuthorized(req)) {
294→        res.writeHead(401);
295→        res.end(JSON.stringify({ success: false, message: 'Unauthorized' }));
296→        return;
297→      }
298→
299→      const success = await triggerLogout();
300→      if (success) {
301→        res.writeHead(200);
302→        res.end(JSON.stringify({ success: true, message: 'Logged out successfully' }));
303→      } else {
304→        res.writeHead(500);
305→        res.end(JSON.stringify({ success: false, message: 'Logout failed or not available' }));
306→      }
307→      return;
308→    }
309→
310→    if (req.method === 'POST' && url === '/api/whatsapp/start') {
311→      res.setHeader('Content-Type', 'application/json');
312→      if (!isAdminAuthorized(req)) {
313→        res.writeHead(401);
314→        res.end(JSON.stringify({ success: false, message: 'Unauthorized' }));
315→        return;
316→      }
317→      const success = await triggerWhatsAppStart();
318→      if (success) {
319→        res.writeHead(200);
320→        res.end(JSON.stringify({ success: true, message: 'WhatsApp startup requested' }));
321→      } else {
322→        res.writeHead(500);
323→        res.end(JSON.stringify({ success: false, message: 'WhatsApp start unavailable or failed' }));
324→      }
325→      return;
326→    }
327→
328→    if (req.method === 'POST' && url === '/api/whatsapp/restart') {
329→      res.setHeader('Content-Type', 'application/json');
330→      if (!isAdminAuthorized(req)) {
331→        res.writeHead(401);
332→        res.end(JSON.stringify({ success: false, message: 'Unauthorized' }));
333→        return;
334→      }
335→      const success = await triggerWhatsAppRestart();
336→      if (success) {
337→        res.writeHead(200);
338→        res.end(JSON.stringify({ success: true, message: 'WhatsApp restart requested' }));
339→      } else {
340→        res.writeHead(500);
341→        res.end(JSON.stringify({ success: false, message: 'WhatsApp restart unavailable or failed' }));
342→      }
343→      return;
344→    }
345→
346→    // Hot-reload configuration from mounted .env file
347→    if (req.method === 'POST' && url === '/api/config/reload') {
348→      res.setHeader('Content-Type', 'application/json');
349→
350→      if (!isAdminAuthorized(req)) {
351→        res.writeHead(401);
352→        res.end(JSON.stringify({ success: false, message: 'Unauthorized' }));
353→        return;
354→      }
355→
356→      try {
357→        const updatedKeys = reloadEnvFromFile();
358→
359→        logger.info(`Config reload: ${updatedKeys.length} key(s) updated${updatedKeys.length > 0 ? ': ' + updatedKeys.join(', ') : ''}`);
360→
361→        res.writeHead(200);
362→        res.end(JSON.stringify({
363→          success: true,
364→          updatedKeys,
365→          message: `${updatedKeys.length} key(s) updated`,
366→        }));
367→      } catch (err) {
368→        logger.error('Config reload failed:', err);
369→        res.writeHead(500);
370→        res.end(JSON.stringify({ success: false, message: 'Reload failed' }));
371→      }
372→      return;
373→    }
374→
375→    // Documentation Routes
376→    if (req.method === 'GET' && (url === '/docs' || url === '/docs/')) {
377→      res.writeHead(302, { Location: '/docs/index.html' });
378→      res.end();
379→      return;
380→    }
381→
382→    if (req.method === 'GET' && url.startsWith('/docs/')) {
383→      // Redirect markdown navigation to viewer (e.g. /docs/SETUP_GUIDE.md -> /docs/index.html#SETUP_GUIDE)
384→      // We check Sec-Fetch-Mode to distinguish between browser navigation and fetch() requests
385→      if (url.endsWith('.md') && req.headers['sec-fetch-mode'] === 'navigate') {
386→        const basename = path.basename(url, '.md');
387→        res.writeHead(302, { Location: `/docs/index.html#${basename}` });
388→        res.end();
389→        return;
390→      }
391→
392→      const filePath = path.join(DOCS_PATH, url.slice(6)); // Remove '/docs/'
393→      serveStaticFile(filePath, res);
394→      return;
395→    }
396→
397→    // Root redirect to docs
398→    if (req.method === 'GET' && url === '/') {
399→      res.writeHead(302, { Location: '/docs/' });
400→      res.end();
401→      return;
402→    }
403→
404→    // Redirect root README to docs viewer
405→    if (req.method === 'GET' && url === '/README.md') {
406→      res.writeHead(302, { Location: '/docs/index.html#README' });
407→      res.end();
408→      return;
409→    }
410→
411→
412→
413→    // GET /api/sessions
414→    if (req.method === 'GET' && url === '/api/sessions') {
415→      res.setHeader('Content-Type', 'application/json');
416→
417→      if (!isAdminAuthorized(req)) {
418→        res.writeHead(401);
419→        res.end(JSON.stringify({ success: false, message: 'Unauthorized' }));
420→        return;
421→      }
422→
423→      try {
424→        const manager = await getSessionManager();
425→        const sessions = await manager.listSessions(100); // Limit to 100 for now
426→
427→        // Return simplified list
428→        const summary = sessions.map(s => ({
429→          id: s.id,
430→          userId: s.userId,
431→          messageCount: s.messages.length,
432→          lastActivityAt: s.lastActivityAt,
433→          createdAt: s.createdAt,
434→          activeProject: s.currentProject?.name || null
435→        }));
436→
437→        res.writeHead(200);
438→        res.end(JSON.stringify({ success: true, sessions: summary }));
439→      } catch (err) {
440→        logger.error('Failed to list sessions:', err);
441→        res.writeHead(500);
442→        res.end(JSON.stringify({ success: false, message: 'Internal server error' }));
443→      }
444→      return;
445→    }
446→
447→    // GET /api/sessions/:id
448→    if (req.method === 'GET' && url.startsWith('/api/sessions/')) {
449→      res.setHeader('Content-Type', 'application/json');
450→
451→      if (!isAdminAuthorized(req)) {
452→        res.writeHead(401);
453→        res.end(JSON.stringify({ success: false, message: 'Unauthorized' }));
454→        return;
455→      }
456→
457→      const parts = url.split('/');
458→      const sessionId = parts[3];
459→      if (!sessionId) {
460→        res.writeHead(400);
461→        res.end(JSON.stringify({ success: false, message: 'Missing session ID' }));
462→        return;
463→      }
464→      if (parts.length !== 4 || !isValidSessionId(sessionId)) {
465→        res.writeHead(400);
466→        res.end(JSON.stringify({ success: false, message: 'Invalid session ID' }));
467→        return;
468→      }
469→
470→      try {
471→        const manager = await getSessionManager();
472→        const session = await manager.getSessionById(sessionId);
473→
474→        if (session) {
475→          res.writeHead(200);
476→          res.end(JSON.stringify({ success: true, session }));
477→        } else {
478→          res.writeHead(404);
479→          res.end(JSON.stringify({ success: false, message: 'Session not found' }));
480→        }
481→      } catch (err) {
482→        logger.error(`Failed to get session ${sessionId}:`, err);
483→        res.writeHead(500);
484→        res.end(JSON.stringify({ success: false, message: 'Internal server error' }));
485→      }
486→      return;
487→    }
488→
489→    // DELETE /api/sessions/:id
490→    if (req.method === 'DELETE' && url.startsWith('/api/sessions/')) {
491→      res.setHeader('Content-Type', 'application/json');
492→
493→      if (!isAdminAuthorized(req)) {
494→        res.writeHead(401);
495→        res.end(JSON.stringify({ success: false, message: 'Unauthorized' }));
496→        return;
497→      }
498→
499→      const parts = url.split('/');
500→      const sessionId = parts[3];
501→      if (!sessionId) {
502→        res.writeHead(400);
503→        res.end(JSON.stringify({ success: false, message: 'Missing session ID' }));
504→        return;
505→      }
506→      if (parts.length !== 4 || !isValidSessionId(sessionId)) {
507→        res.writeHead(400);
508→        res.end(JSON.stringify({ success: false, message: 'Invalid session ID' }));
509→        return;
510→      }
511→
512→      try {
513→        const manager = await getSessionManager();
514→        const success = await manager.deleteSession(sessionId);
515→
516→        if (success) {
517→          res.writeHead(200);
518→          res.end(JSON.stringify({ success: true, message: 'Session deleted' }));
519→        } else {
520→          res.writeHead(404);
521→          res.end(JSON.stringify({ success: false, message: 'Session not found' }));
522→        }
523→      } catch (err) {
524→        logger.error(`Failed to delete session ${sessionId}:`, err);
525→        res.writeHead(500);
526→        res.end(JSON.stringify({ success: false, message: 'Internal server error' }));
527→      }
528→      return;
529→    }
530→
531→    // POST /api/sessions/:id/clear
532→    if (req.method === 'POST' && url.startsWith('/api/sessions/') && url.endsWith('/clear')) {
533→      res.setHeader('Content-Type', 'application/json');
534→
535→      if (!isAdminAuthorized(req)) {
536→        res.writeHead(401);
537→        res.end(JSON.stringify({ success: false, message: 'Unauthorized' }));
538→        return;
539→      }
540→
541→      const parts = url.split('/');
542→      const sessionId = parts[3]; // /api/sessions/:id/clear
543→      if (parts.length !== 5 || parts[4] !== 'clear' || !sessionId || !isValidSessionId(sessionId)) {
544→        res.writeHead(400);
545→        res.end(JSON.stringify({ success: false, message: 'Invalid session ID' }));
546→        return;
547→      }
548→
549→      try {
550→        const manager = await getSessionManager();
551→        const cleared = await manager.clearSession(sessionId);
552→
553→        if (cleared) {
554→          res.writeHead(200);
555→          res.end(JSON.stringify({ success: true, message: 'Session cleared' }));
556→        } else {
557→          res.writeHead(404);
558→          res.end(JSON.stringify({ success: false, message: 'Session not found' }));
559→        }
560→      } catch (err) {
561→        logger.error(`Failed to clear session ${sessionId}:`, err);
562→        res.writeHead(500);
563→        res.end(JSON.stringify({ success: false, message: 'Internal server error' }));
564→      }
565→      return;
566→    }
567→
568→    // 404
569→    res.setHeader('Content-Type', 'application/json');
570→    res.writeHead(404);
571→    res.end(JSON.stringify({ error: 'Not found' }));
572→  });
573→
574→  server.listen(PORT, '0.0.0.0', () => {
575→    logger.info(`Status API listening on port ${PORT}`);
576→    logger.info(`Documentation available at http://localhost:${PORT}/docs`);
577→    if (!env.ADMIN_TOKEN) logger.info('Admin token not set; admin endpoints allow local access.');
578→  });
579→
580→  if (!envWatcherInitialized) {
581→    envWatcherInitialized = true;
582→    fs.watchFile(ENV_PATH, { interval: 1000 }, (curr, prev) => {
583→      if (curr.mtimeMs === prev.mtimeMs) return;
584→      try {
585→        const updatedKeys = reloadEnvFromFile();
586→        if (updatedKeys.length > 0) {
587→          logger.info(`Auto-reloaded .env: ${updatedKeys.length} key(s) updated: ${updatedKeys.join(', ')}`);
588→        }
589→      } catch (error) {
590→        logger.warn(`Auto-reload from .env failed: ${error instanceof Error ? error.message : String(error)}`);
591→      }
592→    });
593→  }
594→
595→  server.on('error', (err) => {
596→    logger.error('Status API server error:', err);
597→  });
598→}
599→
600→/**
601→ * Serve a static docs asset with basic path validation and content-type mapping.
602→ */
603→function serveStaticFile(filePath: string, res: http.ServerResponse): void {
604→  // Security: prevent directory traversal
605→  const normalizedPath = path.normalize(filePath);
606→  if (!normalizedPath.startsWith(DOCS_PATH)) {
607→    res.writeHead(403);
608→    res.end('Forbidden');
609→    return;
610→  }
611→
612→  // Content type mapping
613→  const ext = path.extname(filePath).toLowerCase();
614→  const contentTypes: Record<string, string> = {
615→    '.html': 'text/html; charset=utf-8',
616→    '.css': 'text/css; charset=utf-8',
617→    '.js': 'application/javascript; charset=utf-8',
618→    '.json': 'application/json; charset=utf-8',
619→    '.md': 'text/markdown; charset=utf-8',
620→    '.svg': 'image/svg+xml',
621→    '.png': 'image/png',
622→    '.jpg': 'image/jpeg',
623→    '.jpeg': 'image/jpeg',
624→    '.gif': 'image/gif',
625→    '.ico': 'image/x-icon',
626→  };
627→
628→  fs.readFile(normalizedPath, (err, data) => {
629→    if (err) {
630→      if (err.code === 'ENOENT') {
631→        res.writeHead(404);
632→        res.end('Not found');
633→      } else {
634→        res.writeHead(500);
635→        res.end('Internal server error');
636→      }
637→      return;
638→    }
639→
640→    const contentType = contentTypes[ext] || 'application/octet-stream';
641→    res.setHeader('Content-Type', contentType);
642→    res.writeHead(200);
643→    res.end(data);
644→  });
645→}
